<script lang="ts">
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { onMount } from "svelte";
	import { nativeAuthority } from "$platform/mutation-authority";
	import { setComments } from "./context.svelte";

	const {
		thread,
		children
	}: {
		thread: Thread;
		children: any;
	} = $props();

	// svelte-ignore state_referenced_locally
	let stats = $state(thread.relationships.stats);
	let voteState = $state<number>();
	let feed = $state<ReplyFeedResponse>();

	const comments = setComments({
		// svelte-ignore state_referenced_locally
		thread: () => thread,
		stats: () => stats,
		setStats: (value: ThreadStats) => (stats = value),
		voteState: () => voteState,
		setVoteState: (value: number | undefined) => (voteState = value),
		feed: () => feed,
		setFeed: (value: ReplyFeedResponse | undefined) => (feed = value)
	});

	let discussionContext = "";
	$effect(() => {
		const context = JSON.stringify([thread.id, $nativeAuthority.actor, $nativeAuthority.epoch]);
		if (context === discussionContext) return;
		discussionContext = context; stats = { ...thread.relationships.stats }; voteState = undefined; feed = undefined;
		comments.body = ""; comments.isEdit = false; comments.editTarget = undefined;
	});
	onMount(() => {
		const targetPage = (page.data as any).targetPage;
		if (targetPage) {
			const q = new URLSearchParams(window.location.search);
			q.set("page", String(targetPage));

			const target = window.location.pathname + q.toString();
			if (target !== window.location.href) {
				replaceState(target, page.state);
			}
		}
	});
</script>

{#key JSON.stringify([thread.id, $nativeAuthority.actor, $nativeAuthority.epoch])}
	{@render children()}
{/key}
